import app from 'flarum/admin/app';
/**
 * Create or change a queue or rule. Not Model#save: that drops a
 * relationship set to null ("no queue", "no one").
 */
export function save(type, id, attributes, relationships = {}) {
  const rels = {};
  for (const [key, value] of Object.entries(relationships)) {
    const ident = model => ({
      type: model.data.type,
      id: model.id()
    });
    rels[key] = {
      data: Array.isArray(value) ? value.map(ident) : value ? ident(value) : null
    };
  }
  const data = {
    type,
    attributes,
    relationships: rels
  };
  if (id) data.id = id;
  return app.request({
    method: id ? 'PATCH' : 'POST',
    url: `${app.forum.attribute('apiUrl')}/${type}${id ? '/' + id : ''}`,
    body: {
      data
    }
  }).then(payload => app.store.pushPayload(payload));
}
export function saveOrder(type, ids) {
  return app.request({
    method: 'POST',
    url: `${app.forum.attribute('apiUrl')}/docket-order?type=${type}`,
    body: {
      order: ids
    }
  });
}